-- =============================================================================
-- File: AIMAC_DATA_DIR/schema/013_model_categories_request.sql
-- =============================================================================

-- model_categories_request: one row per batch x model × category
-- This table will be a one to many relationship with model_categories_responses table.
-- The filesystem path for the output of HTML generated by the model will be output/{batch_date}/{batch_time}/batch_{batches.id}/{company_slug}/{model_slug}/{category_slug}/{model_categories_request.pk}.(html|png|axe.json)

-- The system_prompt comes from the view_system_prompt_active table (012_view_system_prompt_active.sql)
-- The user_prompt comes from the categories table (005_categories.sql)

-- =============================================================================
-- TABLE DEFINITION
-- =============================================================================

CREATE TABLE IF NOT EXISTS "model_categories_request" (
    "pk"                    INTEGER PRIMARY KEY AUTOINCREMENT, -- primary key

    -- foreign keys
    "batches_fk_pk"           INTEGER NOT NULL REFERENCES "batches" ("pk") ON DELETE CASCADE,
    "models_fk_pk"           INTEGER NOT NULL REFERENCES "models" ("pk") ON DELETE RESTRICT,
    "categories_fk_pk"         INTEGER NOT NULL REFERENCES "categories" ("pk") ON DELETE RESTRICT,
    -- Links to the specific system prompt used for this request (for auditability).
    -- App logic reads from system_prompt_active singleton, then stores the FK here.
    "system_prompts_fk_pk" INTEGER NOT NULL REFERENCES "system_prompts" ("pk") ON DELETE RESTRICT,

    -- OpenRouter request body: Complete request JSON ready to send to API
    -- Generated from system_prompts and categories tables data
    -- Includes: model, messages, usage:{include:true}
    "openrouter_request_body" TEXT NOT NULL CHECK (json_valid("openrouter_request_body")), -- Raw OpenRouter request JSON

    -- Timestamps
    "created_at"            DATETIME DEFAULT (CURRENT_TIMESTAMP),
    "updated_at"            DATETIME DEFAULT (CURRENT_TIMESTAMP) -- Updated via trigger on row modification
);

-- =============================================================================
-- INDEXES
-- =============================================================================

-- Batch-level queries: all requests for a given batch
CREATE INDEX IF NOT EXISTS "idx_model_categories_request_batch"
    ON "model_categories_request" ("batches_fk_pk");
-- Model-level queries: all requests for a given model across batches
CREATE INDEX IF NOT EXISTS "idx_model_categories_request_model"
    ON "model_categories_request" ("models_fk_pk");
-- Category-level queries: all requests for a given category
CREATE INDEX IF NOT EXISTS "idx_model_categories_request_category"
    ON "model_categories_request" ("categories_fk_pk");
-- Enforce uniqueness via unique index: one request per batch/model/category
-- (This also covers the primary lookup use case - no separate non-unique index needed)
CREATE UNIQUE INDEX IF NOT EXISTS "uniq_model_categories_request_bmc"
    ON "model_categories_request" ("batches_fk_pk", "models_fk_pk", "categories_fk_pk");

-- Optimized for WHERE (models_fk_pk, categories_fk_pk) IN (...) queries
-- Supports ORDER BY models_fk_pk, categories_fk_pk without filesort
-- Used by leaderboard and category cost queries
CREATE INDEX IF NOT EXISTS "idx_mcr_model_category_pk"
    ON "model_categories_request" ("models_fk_pk", "categories_fk_pk", "pk");

-- =============================================================================
-- TRIGGERS
-- =============================================================================

-- Note: openrouter_request_body is generated by app logic (executor.py) at insert time,
-- not via trigger, since it requires async API calls and complex message formatting.

-- Update the updated_at timestamp on any row update
CREATE TRIGGER IF NOT EXISTS trg_model_categories_request_updated_at
AFTER UPDATE ON "model_categories_request"
FOR EACH ROW
BEGIN
    UPDATE "model_categories_request"
    SET "updated_at" = CURRENT_TIMESTAMP
    WHERE "pk" = NEW."pk";
END;
